1	#!/usr/bin/env node
2	// Manages the local `.env` across environment tiers (dev/test/sit/uat/staging/prod).
3	//
4	// Storage: .env.sample documents every key with a `# scope:shared|tier|personal|auto`
5	// comment on its own line above the key. Real values live in gitignored
6	// .env.shared (same across all tiers) and .env.<tier> (differs per tier) —
7	// never committed.
8	//
9	// Usage:
10	//   node scripts/switchEnv.mjs                — report the currently active tier
11	//   node scripts/switchEnv.mjs init            — scaffold .env.shared + every
12	//                                                 .env.<tier> at once (skips files
13	//                                                 that already exist), so a dev can
14	//                                                 fill in all tokens in one pass
15	//                                                 instead of tier by tier
16	//   node scripts/switchEnv.mjs validate [--live] — check every existing .env.shared /
17	//                                                 .env.<tier> file against
18	//                                                 .env.sample's schema, plus
19	//                                                 cross-checks (OCAPI host vs
20	//                                                 config/<tier>.js, Contentful
21	//                                                 environment id vs tier). With
22	//                                                 --live, also makes a real
23	//                                                 read-only Contentful Delivery
24	//                                                 API call AND a real SLAS guest
25	//                                                 (client_credentials) token
26	//                                                 request per tier, confirming
27	//                                                 the credentials actually work
28	//                                                 — not just that they're set
29	//   node scripts/switchEnv.mjs <tier>          — switch to <tier>, merging
30	//                                                 .env.shared + .env.<tier> into
31	//                                                 .env (tier values win on
32	//                                                 collision) and stamping
33	//                                                 ENVIRONMENT_NAME + DEPLOY_TARGET
34	//
35	// `init` also auto-fetches CONTENTFUL_ENVIRONMENT_ID, CONTENTFUL_DELIVERY_TOKEN,
36	// and CONTENTFUL_PREVIEW_TOKEN for every tier once .env.shared has a
37	// CONTENTFUL_MANAGEMENT_TOKEN + CONTENTFUL_SPACE_ID — reusing the same Content
38	// Management API read (client.apiKey.getMany / client.previewApiKey.get) and
39	// the same @ZimmermannAU/tier-1-approvers write gate as `npm run
40	// config:contentful` (scripts/contentful/setup/getConfig.mjs). The environment
41	// id comes from the same call — an API key's `environments` link only ever
42	// points at a real environment, so finding a token for a tier also confirms
43	// that tier's environment exists. It only reads existing API keys/environments
44	// — it never creates new ones in Contentful.
45	//
46	// SFCC values (org id, short code, OCAPI host, SLAS client id/secret) are NOT
47	// auto-fetched: there's no discovery API (you need the short code to call any
48	// SFCC API in the first place), and OAuth client secrets are never retrievable
49	// after creation. See .docs/integration/01-sfcc.md — these remain manual entry.
50	import fs from 'node:fs';
51	import path from 'node:path';
52	import { execSync } from 'node:child_process';
53	import { createClient as createContentfulClient } from './contentful/setup/_shared.mjs';
54	
55	const ROOT = process.cwd();
56	const TIERS = ['dev', 'test', 'sit', 'uat', 'staging', 'prod'];
57	// DEPLOY_TARGET picks config/{target}.js in pwa-kit-runtime's getConfig(), and also
58	// names the config file on disk for the cross-checks below. `prod` is the only tier
59	// where the local slug and the file/MRT target name diverge — see
60	// config/production.js and the `push:prod -t production` npm script.
61	const DEPLOY_TARGET_MAP = {
62	  dev: 'dev',
63	  test: 'test',
64	  sit: 'sit',
65	  uat: 'uat',
66	  staging: 'staging',
67	  prod: 'production',
68	};
69	// Confirmed environment strategy (2026-07-11): single Contentful space, per-tier
70	// environment id. `prod` is the only tier that doesn't just reuse its own slug.
71	const CONTENTFUL_ENV_MAP = {
72	  dev: 'dev',
73	  test: 'test',
74	  sit: 'sit',
75	  uat: 'uat',
76	  staging: 'staging',
77	  prod: 'master',
78	};
79	
80	function readEnvFile(filePath) {
81	  if (!fs.existsSync(filePath)) return null;
82	  const entries = [];
83	  for (const raw of fs.readFileSync(filePath, 'utf8').split('\n')) {
84	    const line = raw.trim();
85	    if (!line || line.startsWith('#')) continue;
86	    const eqIdx = line.indexOf('=');
87	    if (eqIdx === -1) continue;
88	    entries.push([line.slice(0, eqIdx).trim(), line.slice(eqIdx + 1).trim()]);
89	  }
90	  return entries;
91	}
92	
93	// Section headers look like `# ── Commerce / SFCC ───────────────`.
94	const SECTION_HEADER_RE = /^#\s*──+\s*(.+?)\s*──+\s*$/;
95	// Scope tags are their own comment line immediately above the KEY=value line
96	// (not trailing on the same line) — a trailing comment would make a blank
97	// placeholder look non-empty to the pre-commit .env.sample secret guard,
98	// which just checks whether anything follows the `=`.
99	const SCOPE_TAG_RE = /^#\s*scope:(shared|tier|personal|auto)\s*$/;
100	
101	function parseSample() {
102	  const samplePath = path.join(ROOT, '.env.sample');
103	  const parsed = [];
104	  let currentSection = null;
105	  let pendingScope = null;
106	  for (const raw of fs.readFileSync(samplePath, 'utf8').split('\n')) {
107	    const line = raw.trim();
108	    const sectionMatch = line.match(SECTION_HEADER_RE);
109	    if (sectionMatch) {
110	      currentSection = sectionMatch[1];
111	      continue;
112	    }
113	    const scopeMatch = line.match(SCOPE_TAG_RE);
114	    if (scopeMatch) {
115	      pendingScope = scopeMatch[1];
116	      continue;
117	    }
118	    if (!line || line.startsWith('#')) continue;
119	    if (!pendingScope) continue; // a KEY=value line with no scope tag above it — not managed
120	    const eqIdx = line.indexOf('=');
121	    if (eqIdx === -1) {
122	      pendingScope = null;
123	      continue;
124	    }
125	    parsed.push({
126	      key: line.slice(0, eqIdx).trim(),
127	      value: line.slice(eqIdx + 1).trim(),
128	      scope: pendingScope,
129	      section: currentSection || 'Other',
130	    });
131	    pendingScope = null;
132	  }
133	  return parsed;
134	}
135	
136	// Groups already-ordered entries by their .env.sample section, preserving the
137	// order sections first appear in. Used to print generated files with the same
138	// "# ── Section ──" grouping .env.sample has, instead of one flat key list.
139	function groupBySection(entries) {
140	  const groups = [];
141	  const bySection = new Map();
142	  for (const entry of entries) {
143	    if (!bySection.has(entry.section)) {
144	      const group = { section: entry.section, entries: [] };
145	      bySection.set(entry.section, group);
146	      groups.push(group);
147	    }
148	    bySection.get(entry.section).entries.push(entry);
149	  }
150	  return groups;
151	}
152	
153	const SAMPLE = parseSample();
154	const SHARED_ENTRIES = SAMPLE.filter((entry) => entry.scope === 'shared');
155	const TIER_ENTRIES = SAMPLE.filter((entry) => entry.scope === 'tier');
156	const PERSONAL_ENTRIES = SAMPLE.filter((entry) => entry.scope === 'personal');
157	const SHARED_KEYS = new Set(SHARED_ENTRIES.map((entry) => entry.key));
158	const TIER_KEYS = new Set(TIER_ENTRIES.map((entry) => entry.key));
159	const PERSONAL_KEYS = new Set(PERSONAL_ENTRIES.map((entry) => entry.key));
160	// Everything that legitimately lives in .env.shared — shared (centralizable)
161	// plus personal (tier-independent, but per-developer and never centralized).
162	const SHARED_FILE_ENTRIES = [...SHARED_ENTRIES, ...PERSONAL_ENTRIES];
163	const SHARED_FILE_KEYS = new Set([...SHARED_KEYS, ...PERSONAL_KEYS]);
164	const AUTO_KEYS = new Set(SAMPLE.filter((entry) => entry.scope === 'auto').map((entry) => entry.key));
165	
166	function scaffold(filePath, keys, label, carryDefaults) {
167	  const header = carryDefaults
168	    ? `# Generated by scripts/switchEnv.mjs — fill in real ${label} values.\n` +
169	      `# Gitignored — never commit this file. Values already in .env.sample (known\n` +
170	      `# public identifiers, e.g. GTM container ID) are carried over as a starting point.\n\n`
171	    : `# Generated by scripts/switchEnv.mjs — fill in real ${label} values.\n` +
172	      `# Gitignored — never commit this file. Tier-specific values always start blank\n` +
173	      `# here (even if .env.sample shows an example) — never copy another tier's value.\n\n`;
174	  const body =
175	    groupBySection(keys)
176	      .map(({ section, entries }) => {
177	        const groupLines = entries.map(({ key, value }) => `${key}=${carryDefaults ? value : ''}`);
178	        return `# ── ${section} ──\n${groupLines.join('\n')}`;
179	      })
180	      .join('\n\n') + '\n';
181	  fs.writeFileSync(filePath, header + body);
182	  const blankCount = carryDefaults ? keys.filter(({ value }) => !value).length : keys.length;
183	  console.log(
184	    `Created ${path.relative(
185	      ROOT,
186	      filePath,
187	    )} — fill in the ${blankCount} blank value(s) before switching to this tier.`,
188	  );
189	  return blankCount;
190	}
191	
192	function reportCurrent() {
193	  const current = readEnvFile(path.join(ROOT, '.env'));
194	  const envName = current?.find(([key]) => key === 'ENVIRONMENT_NAME')?.[1] || '(not set)';
195	  console.log(`Current tier: ${envName}`);
196	  printUsage();
197	}
198	
199	function printUsage() {
200	  console.log(`\nAvailable tiers: ${TIERS.join(', ')}`);
201	  console.log('Usage:');
202	  console.log('  npm run env                 — report the current tier');
203	  console.log('  npm run env -- init            — scaffold every .env.shared / .env.<tier> at once,');
204	  console.log('                                   pull values from GitHub Environments, then');
205	  console.log('                                   auto-fill Contentful tokens if possible');
206	  console.log('  npm run env -- validate        — check all existing env files for mistakes');
207	  console.log('  npm run env -- validate --live — also confirm Contentful + SFCC credentials actually work');
208	  console.log(`  npm run env -- push <${GH_SCOPES.join('|')}>`);
209	  console.log('                                   — tier-1-approvers only: push local values up to');
210	  console.log('                                   the matching GitHub Environment');
211	  console.log('  npm run env -- <tier>          — switch to <tier>');
212	}
213	
214	async function initAll() {
215	  const sharedPath = path.join(ROOT, '.env.shared');
216	  const created = [];
217	  const skipped = [];
218	  let totalBlanks = 0;
219	
220	  if (fs.existsSync(sharedPath)) {
221	    skipped.push('.env.shared');
222	  } else {
223	    totalBlanks += scaffold(sharedPath, SHARED_FILE_ENTRIES, 'shared (all tiers)', true);
224	    created.push('.env.shared');
225	  }
226	
227	  for (const tier of TIERS) {
228	    const tierPath = path.join(ROOT, `.env.${tier}`);
229	    if (fs.existsSync(tierPath)) {
230	      skipped.push(`.env.${tier}`);
231	    } else {
232	      totalBlanks += scaffold(tierPath, TIER_ENTRIES, tier, false);
233	      created.push(`.env.${tier}`);
234	    }
235	  }
236	
237	  console.log('');
238	  if (created.length) {
239	    console.log(`Created ${created.length} file(s): ${created.join(', ')}`);
240	    console.log(`Fill in the ${totalBlanks} blank value(s) across them in one pass, then run:`);
241	    console.log('  npm run env -- validate     (check everything is filled in correctly)');
242	    console.log('  npm run env -- <tier>       (activate one)');
243	  } else {
244	    console.log('Nothing to do — every .env.shared / .env.<tier> file already exists.');
245	  }
246	  if (skipped.length) {
247	    console.log(`Already existed, left untouched: ${skipped.join(', ')}`);
248	  }
249	
250	  migrateSharedFromDotEnv();
251	  pullFromGitHubEnvironments();
252	  await syncContentfulTokens();
253	}
254	
255	// ── GitHub Environments (centralized shared/tier storage) ──────────────────
256	// One GitHub Environment per scope — "shared" plus one per tier — each holding
257	// that scope's values as Environment-level Variables. Reading a Variable only
258	// needs repo collaborator access (gh auto-detects the repo from cwd, no need
259	// to pass -R). Writing needs repo Admin, which every tier-1-approver already
260	// holds — see `push` in main(). This intentionally stores real secrets here
261	// (not just non-sensitive config) — a deliberate, confirmed override of
262	// AGENTS.md's "secrets only in .env / Managed Runtime" rule, accepting that
263	// GitHub Variables are plaintext and readable by any repo collaborator.
264	const GH_SCOPES = ['shared', ...TIERS];
265	
266	function listGitHubVariables(scope) {
267	  try {
268	    const raw = execSync(`gh variable list --env ${scope} --json name,value`, {
269	      encoding: 'utf8',
270	      stdio: ['ignore', 'pipe', 'pipe'],
271	    });
272	    return JSON.parse(raw);
273	  } catch {
274	    return null; // not authenticated, no access, or environment missing
275	  }
276	}
277	
278	function pullFromGitHubEnvironments() {
279	  console.log('\nPulling values from GitHub Environments...');
280	  for (const scope of GH_SCOPES) {
281	    const filePath = path.join(ROOT, scope === 'shared' ? '.env.shared' : `.env.${scope}`);
282	    if (!fs.existsSync(filePath)) continue;
283	    const remoteVars = listGitHubVariables(scope);
284	    if (!remoteVars) {
285	      console.log(`  ${scope}: could not reach GitHub (not authenticated, no access, or environment missing)`);
286	      continue;
287	    }
288	    // Personal-scope keys (e.g. JIRA_API_TOKEN, CONTENTFUL_MANAGEMENT_TOKEN) are
289	    // never pulled, even if one somehow ended up on GitHub — each developer's
290	    // own value must never be overwritten by whoever last pushed.
291	    const filtered = scope === 'shared' ? remoteVars.filter(({ name }) => !PERSONAL_KEYS.has(name)) : remoteVars;
292	    const skippedPersonal = remoteVars.length - filtered.length;
293	    const updates = Object.fromEntries(filtered.map(({ name, value }) => [name, value]));
294	    const changes = upsertKeys(filePath, updates, true);
295	    const summary = changes.length
296	      ? changes.map((change) => `${change.action} ${change.key}`).join(', ')
297	      : 'already up to date';
298	    console.log(
299	      `  ${scope}: ${summary}${
300	        skippedPersonal ? ` (ignored ${skippedPersonal} personal-scope value(s) found on GitHub — see NOTE below)` : ''
301	      }`,
302	    );
303	  }
304	}
305	
306	function pushToGitHubEnvironment(scope) {
307	  const filePath = path.join(ROOT, scope === 'shared' ? '.env.shared' : `.env.${scope}`);
308	  if (!fs.existsSync(filePath)) {
309	    console.error(`${path.relative(ROOT, filePath)} doesn't exist yet — run \`npm run env -- init\` first.`);
310	    process.exit(1);
311	  }
312	
313	  const { approved, login } = isTier1Approver();
314	  if (!approved) {
315	    console.log(
316	      `Authenticated as '${login}' — not a tier-1-approver. Only tier-1-approvers can push to GitHub Environments.`,
317	    );
318	    return;
319	  }
320	
321	  const allEntries = readEnvFile(filePath).filter(([, value]) => value);
322	  // Personal-scope keys never leave this machine — pushing your own Jira/CMA
323	  // token would put every teammate's actions under your identity.
324	  const entries = scope === 'shared' ? allEntries.filter(([key]) => !PERSONAL_KEYS.has(key)) : allEntries;
325	  const skippedPersonal = allEntries.length - entries.length;
326	  if (skippedPersonal) {
327	    console.log(
328	      `Excluding ${skippedPersonal} personal-scope value(s) — these are never pushed: ${allEntries
329	        .filter(([key]) => PERSONAL_KEYS.has(key))
330	        .map(([key]) => key)
331	        .join(', ')}`,
332	    );
333	  }
334	  if (!entries.length) {
335	    console.log(`Nothing to push — ${path.relative(ROOT, filePath)} has no filled-in, push-eligible values yet.`);
336	    return;
337	  }
338	
339	  const tempFile = path.join(ROOT, `.env.push-${scope}.tmp`);
340	  fs.writeFileSync(tempFile, entries.map(([key, value]) => `${key}=${value}`).join('\n') + '\n');
341	  try {
342	    execSync(`gh variable set -f "${tempFile}" --env ${scope}`, { stdio: 'inherit' });
343	    console.log(`Pushed ${entries.length} value(s) to the "${scope}" GitHub Environment.`);
344	  } finally {
345	    fs.unlinkSync(tempFile);
346	  }
347	}
348	
349	// ── Contentful auto-fetch (init) ────────────────────────────────────────────
350	// Same tier-1-approver gate as scripts/contentful/setup/getConfig.mjs — kept as
351	// a small local copy rather than importing it, since it isn't exported there.
352	function isTier1Approver() {
353	  try {
354	    const login = execSync('gh api user --jq .login', { encoding: 'utf8' }).trim();
355	    const membersRaw = execSync("gh api orgs/ZimmermannAU/teams/tier-1-approvers/members --jq '.[].login'", {
356	      encoding: 'utf8',
357	    }).trim();
358	    const members = membersRaw.split('\n').filter(Boolean);
359	    return { approved: members.includes(login), login };
360	  } catch {
361	    return { approved: false, login: 'unknown' };
362	  }
363	}
364	
365	// contentful-management errors stringify their `.message` as the full raw API
366	// error body (headers, request id, everything) — pull out just the human part.
367	function contentfulErrorMessage(err) {
368	  try {
369	    const parsed = JSON.parse(err.message);
370	    if (parsed?.message) return parsed.message;
371	  } catch {
372	    // not JSON — fall through to the raw message
373	  }
374	  return err.message;
375	}
376	
377	async function fetchContentfulTokenMap(managementToken, spaceId) {
378	  process.env.CONTENTFUL_MANAGEMENT_TOKEN = managementToken;
379	  process.env.CONTENTFUL_SPACE_ID = spaceId;
380	  const client = createContentfulClient();
381	
382	  const { items: apiKeys } = await client.apiKey.getMany({ query: { limit: 100 } });
383	  const tokenMap = {};
384	  for (const key of apiKeys) {
385	    const envLink = key.environments?.[0];
386	    if (!envLink) continue;
387	    const envId = envLink.sys.id;
388	    let previewToken = '';
389	    if (key.preview_api_key?.sys?.id) {
390	      try {
391	        const previewKey = await client.previewApiKey.get({ previewApiKeyId: key.preview_api_key.sys.id });
392	        previewToken = previewKey.accessToken;
393	      } catch {
394	        // non-fatal — preview key may not exist yet
395	      }
396	    }
397	    tokenMap[envId] = { deliveryToken: key.accessToken, previewToken };
398	  }
399	  return tokenMap;
400	}
401	
402	function parseEnvLines(content) {
403	  return content.split('\n').map((line) => {
404	    if (line.startsWith('#') || line.trim() === '') return { type: 'raw', value: line };
405	    const eqIdx = line.indexOf('=');
406	    if (eqIdx === -1) return { type: 'raw', value: line };
407	    return { type: 'var', key: line.slice(0, eqIdx).trim(), value: line.slice(eqIdx + 1) };
408	  });
409	}
410	
411	function serializeEnvLines(lines) {
412	  return lines.map((line) => (line.type === 'var' ? `${line.key}=${line.value}` : line.value)).join('\n');
413	}
414	
415	// Updates only the given keys in place, preserving comments/ordering/everything
416	// else — unlike scaffold(), which is only used for brand-new files. With
417	// fillOnly, an already-non-blank existing value is left alone instead of being
418	// overwritten — used for one-off migration from a pre-existing .env, where we
419	// never want to silently clobber something the dev already set by hand.
420	function upsertKeys(filePath, updates, canWrite, fillOnly = false) {
421	  const lines = parseEnvLines(fs.readFileSync(filePath, 'utf8'));
422	  const changes = [];
423	  for (const [key, value] of Object.entries(updates)) {
424	    if (!value) continue;
425	    const existing = lines.find((line) => line.type === 'var' && line.key === key);
426	    if (!existing) {
427	      lines.push({ type: 'var', key, value });
428	      changes.push({ action: 'add', key });
429	    } else if (!existing.value.trim()) {
430	      existing.value = value;
431	      changes.push({ action: 'fill', key });
432	    } else if (!fillOnly && existing.value.trim() !== value) {
433	      existing.value = value;
434	      changes.push({ action: 'update', key });
435	    }
436	  }
437	  if (changes.length && canWrite) {
438	    fs.writeFileSync(filePath, serializeEnvLines(lines));
439	  }
440	  return changes;
441	}
442	
443	// One-off backfill: if a pre-existing root .env already has real values for
444	// shared-scope keys (e.g. a Contentful management token a dev added before
445	// this tiered setup existed), pull them into .env.shared. Only shared-scope
446	// keys — tier-scope values in an old .env can't be safely attributed to any
447	// one tier, so those are never auto-migrated. No tier-1 gate: this only copies
448	// a secret between two local gitignored files the developer already owns.
449	function migrateSharedFromDotEnv() {
450	  const dotEnvPath = path.join(ROOT, '.env');
451	  const sharedPath = path.join(ROOT, '.env.shared');
452	  if (!fs.existsSync(dotEnvPath) || !fs.existsSync(sharedPath)) return;
453	
454	  const dotEnvMap = new Map(readEnvFile(dotEnvPath));
455	  const updates = {};
456	  for (const key of SHARED_FILE_KEYS) {
457	    const value = dotEnvMap.get(key);
458	    if (value) updates[key] = value;
459	  }
460	  if (!Object.keys(updates).length) return;
461	
462	  const changes = upsertKeys(sharedPath, updates, true, true);
463	  if (changes.length) {
464	    console.log(
465	      `\nFound already-filled value(s) in your existing .env — copied into .env.shared: ${changes
466	        .map((change) => change.key)
467	        .join(', ')}`,
468	    );
469	  }
470	}
471	
472	async function syncContentfulTokens() {
473	  const sharedPath = path.join(ROOT, '.env.shared');
474	  if (!fs.existsSync(sharedPath)) return;
475	
476	  const sharedMap = new Map(readEnvFile(sharedPath));
477	  const managementToken = sharedMap.get('CONTENTFUL_MANAGEMENT_TOKEN');
478	  const spaceId = sharedMap.get('CONTENTFUL_SPACE_ID');
479	  if (!managementToken || !spaceId) {
480	    console.log(
481	      '\n(Skipping Contentful token auto-fetch — fill in CONTENTFUL_MANAGEMENT_TOKEN and CONTENTFUL_SPACE_ID in .env.shared, then run `npm run env -- init` again.)',
482	    );
483	    return;
484	  }
485	
486	  const { approved, login } = isTier1Approver();
487	  console.log(
488	    `\nFetching live Contentful API keys (authenticated as '${login}'${
489	      approved ? ', tier-1-approver' : ' — read-only, not a tier-1-approver'
490	    })...`,
491	  );
492	
493	  let tokenMap;
494	  try {
495	    tokenMap = await fetchContentfulTokenMap(managementToken, spaceId);
496	  } catch (err) {
497	    console.log(`  Could not reach Contentful: ${contentfulErrorMessage(err)}`);
498	    return;
499	  }
500	
501	  for (const tier of TIERS) {
502	    const tierPath = path.join(ROOT, `.env.${tier}`);
503	    if (!fs.existsSync(tierPath)) continue; // init scaffolds these first; nothing to update yet
504	    const contentfulEnvId = CONTENTFUL_ENV_MAP[tier];
505	    const tokens = tokenMap[contentfulEnvId];
506	    if (!tokens) {
507	      console.log(`  ${tier}: no Contentful API key found for environment "${contentfulEnvId}"`);
508	      continue;
509	    }
510	    const changes = upsertKeys(
511	      tierPath,
512	      {
513	        // tokenMap is keyed by real environment IDs from the API key's own
514	        // `environments` link — if we found a token for it, the environment
515	        // definitely exists, so it's safe to fill this in from the same call.
516	        CONTENTFUL_ENVIRONMENT_ID: contentfulEnvId,
517	        CONTENTFUL_DELIVERY_TOKEN: tokens.deliveryToken,
518	        CONTENTFUL_PREVIEW_TOKEN: tokens.previewToken,
519	      },
520	      approved,
521	    );
522	    if (!changes.length) {
523	      console.log(`  ${tier}: already up to date`);
524	    } else if (!approved) {
525	      console.log(`  ${tier}: ${changes.length} change(s) available — read-only, ask a tier-1-approver to run this`);
526	    } else {
527	      console.log(`  ${tier}: ${changes.map((change) => `${change.action} ${change.key}`).join(', ')}`);
528	    }
529	  }
530	}
531	
532	function extractOcapiHost(tier) {
533	  const configPath = path.join(ROOT, 'config', `${DEPLOY_TARGET_MAP[tier]}.js`);
534	  if (!fs.existsSync(configPath)) return null;
535	  const content = fs.readFileSync(configPath, 'utf8');
536	  const match = content.match(/host:\s*'([^']+)'[^}]*path:\s*'ocapi'/);
537	  return match ? match[1] : null;
538	}
539	
540	function validateKeyPlacement(entries, ownScope, ownLabel, otherScope, otherLabel) {
541	  const errors = [];
542	  const warnings = [];
543	  let blankCount = 0;
544	  const seen = new Map();
545	  for (const [key, value] of entries) {
546	    if (seen.has(key)) errors.push(`duplicate key ${key}`);
547	    seen.set(key, value);
548	    if (AUTO_KEYS.has(key)) {
549	      errors.push(`${key} should never be hand-set — it's auto-generated on every switch`);
550	    } else if (otherScope.has(key)) {
551	      errors.push(
552	        `${key} is a ${otherLabel}-scope key — belongs in ${
553	          otherLabel === 'shared' ? '.env.shared' : 'a .env.<tier> file'
554	        }, not here`,
555	      );
556	    } else if (!ownScope.has(key)) {
557	      warnings.push(`${key} isn't in .env.sample — typo, or the sample needs updating`);
558	    }
559	  }
560	  // Blank/missing values are extremely common (most integrations aren't
561	  // provisioned yet) — collapsed to one count instead of one line per key,
562	  // so real problems (errors, misplaced/unknown keys) aren't buried under them.
563	  for (const key of ownScope) {
564	    if (!seen.has(key) || !seen.get(key)) blankCount += 1;
565	  }
566	  return { errors, warnings, blankCount, seen };
567	}
568	
569	function validateSharedFile() {
570	  const filePath = path.join(ROOT, '.env.shared');
571	  if (!fs.existsSync(filePath)) return { skipped: true };
572	  return validateKeyPlacement(readEnvFile(filePath), SHARED_FILE_KEYS, 'shared', TIER_KEYS, 'tier');
573	}
574	
575	function validateTierFile(tier) {
576	  const filePath = path.join(ROOT, `.env.${tier}`);
577	  if (!fs.existsSync(filePath)) return { skipped: true };
578	  const result = validateKeyPlacement(readEnvFile(filePath), TIER_KEYS, 'tier', SHARED_FILE_KEYS, 'shared');
579	
580	  const ocapiHost = result.seen.get('COMMERCE_API_OCAPI_HOST');
581	  if (ocapiHost) {
582	    if (ocapiHost.includes('TODO')) {
583	      result.errors.push(
584	        'COMMERCE_API_OCAPI_HOST still has a TODO placeholder — replace with the real SFCC sandbox host',
585	      );
586	    }
587	    const expectedHost = extractOcapiHost(tier);
588	    if (expectedHost && !ocapiHost.includes('TODO') && ocapiHost !== expectedHost) {
589	      result.errors.push(
590	        `COMMERCE_API_OCAPI_HOST=${ocapiHost} doesn't match config/${DEPLOY_TARGET_MAP[tier]}.js's proxy host (${expectedHost}) — likely copy-pasted from another tier`,
591	      );
592	    }
593	  }
594	
595	  const contentfulEnv = result.seen.get('CONTENTFUL_ENVIRONMENT_ID');
596	  const expectedContentfulEnv = CONTENTFUL_ENV_MAP[tier];
597	  if (contentfulEnv && contentfulEnv !== expectedContentfulEnv) {
598	    result.warnings.push(
599	      `CONTENTFUL_ENVIRONMENT_ID=${contentfulEnv} — expected "${expectedContentfulEnv}" for the ${tier} tier per the confirmed environment strategy`,
600	    );
601	  }
602	
603	  return result;
604	}
605	
606	function printResult(label, result) {
607	  if (result.skipped) {
608	    console.log(`${label}: not created yet (run \`npm run env -- init\`)`);
609	    return false;
610	  }
611	  const { errors, warnings, blankCount } = result;
612	  if (!errors.length && !warnings.length && !blankCount) {
613	    console.log(`${label}: OK`);
614	    return false;
615	  }
616	  console.log(`${label}:`);
617	  errors.forEach((error) => console.log(`  ERROR   ${error}`));
618	  warnings.forEach((warning) => console.log(`  warning ${warning}`));
619	  if (blankCount) {
620	    console.log(`  (${blankCount} blank value(s) in ${label})`);
621	  }
622	  return errors.length > 0;
623	}
624	
625	// Merges .env.shared + .env.<tier> (tier wins on collision). Returns null if
626	// either file doesn't exist yet.
627	function mergeSharedAndTier(tier) {
628	  const sharedPath = path.join(ROOT, '.env.shared');
629	  const tierPath = path.join(ROOT, `.env.${tier}`);
630	  if (!fs.existsSync(sharedPath) || !fs.existsSync(tierPath)) return null;
631	
632	  const merged = new Map();
633	  for (const [key, value] of readEnvFile(sharedPath)) merged.set(key, value);
634	  for (const [key, value] of readEnvFile(tierPath)) merged.set(key, value); // tier wins
635	  merged.delete('ENVIRONMENT_NAME');
636	  merged.delete('DEPLOY_TARGET');
637	  return merged;
638	}
639	
640	// Real, read-only call to the Contentful Content Delivery API — confirms the
641	// delivery token actually authenticates for that space/environment, not just
642	// that it's non-blank.
643	async function liveCheckContentful(tier) {
644	  const merged = mergeSharedAndTier(tier);
645	  if (!merged) return { skipped: true, reason: '.env.shared and/or .env.<tier> not created yet' };
646	
647	  const deliveryToken = merged.get('CONTENTFUL_DELIVERY_TOKEN');
648	  const spaceId = merged.get('CONTENTFUL_SPACE_ID');
649	  const envId = merged.get('CONTENTFUL_ENVIRONMENT_ID');
650	  if (!deliveryToken || !spaceId || !envId) {
651	    return {
652	      skipped: true,
653	      reason: 'CONTENTFUL_DELIVERY_TOKEN / CONTENTFUL_SPACE_ID / CONTENTFUL_ENVIRONMENT_ID not all filled in',
654	    };
655	  }
656	
657	  const url = `https://cdn.contentful.com/spaces/${spaceId}/environments/${envId}/entries?limit=1`;
658	  try {
659	    const res = await fetch(url, { headers: { Authorization: `Bearer ${deliveryToken}` } });
660	    if (res.ok) return { ok: true };
661	    return { ok: false, message: `HTTP ${res.status} from Contentful Delivery API` };
662	  } catch (err) {
663	    return { ok: false, message: `network error — ${err.message}` };
664	  }
665	}
666	
667	// Real, read-only SLAS guest-token request — the same private-client
668	// client_credentials grant every anonymous shopper visit already triggers
669	// (confirmed against the actual commerce-sdk-react/commerce-sdk-isomorphic
670	// `loginGuestUserPrivate` implementation, not guessed). Doesn't touch any
671	// customer/commerce data — just proves the short code, org id, and SLAS
672	// client id/secret are all correct for that tier's SFCC sandbox.
673	async function liveCheckSfcc(tier) {
674	  const merged = mergeSharedAndTier(tier);
675	  if (!merged) return { skipped: true, reason: '.env.shared and/or .env.<tier> not created yet' };
676	
677	  const shortCode = merged.get('COMMERCE_API_SHORT_CODE');
678	  const organizationId = merged.get('COMMERCE_API_ORGANIZATION_ID');
679	  const clientId = merged.get('COMMERCE_API_CLIENT_ID');
680	  const clientSecret = merged.get('PWA_KIT_SLAS_CLIENT_SECRET');
681	  const siteId = merged.get('COMMERCE_API_SITE_ID');
682	  if (!shortCode || !organizationId || !clientId || !clientSecret || !siteId) {
683	    return {
684	      skipped: true,
685	      reason:
686	        'COMMERCE_API_SHORT_CODE / ORGANIZATION_ID / CLIENT_ID / PWA_KIT_SLAS_CLIENT_SECRET / SITE_ID not all filled in',
687	    };
688	  }
689	
690	  const url = `https://${shortCode}.api.commercecloud.salesforce.com/shopper/auth/v1/organizations/${organizationId}/oauth2/token`;
691	  const basicAuth = Buffer.from(`${clientId}:${clientSecret}`).toString('base64');
692	  try {
693	    const res = await fetch(url, {
694	      method: 'POST',
695	      headers: {
696	        Authorization: `Basic ${basicAuth}`,
697	        'Content-Type': 'application/x-www-form-urlencoded',
698	      },
699	      body: new URLSearchParams({ grant_type: 'client_credentials', channel_id: siteId }).toString(),
700	    });
701	    if (res.ok) return { ok: true };
702	    return { ok: false, message: `HTTP ${res.status} from SLAS token endpoint (${shortCode})` };
703	  } catch (err) {
704	    return { ok: false, message: `network error — ${err.message}` };
705	  }
706	}
707	
708	// Runs a live-check function across every tier, printing OK/ERROR per tier
709	// and collapsing skips (missing credentials) to a single trailing count —
710	// same "don't clutter with what can't be tested" approach as the static
711	// blank-value counts above.
712	async function runLiveChecks(sectionLabel, checkFn, okMessage) {
713	  console.log(`\n── Live checks (${sectionLabel}) ──`);
714	  let skippedCount = 0;
715	  let hadError = false;
716	  for (const tier of TIERS) {
717	    const result = await checkFn(tier);
718	    if (result.skipped) {
719	      skippedCount += 1;
720	    } else if (result.ok) {
721	      console.log(`  ${tier}: OK — ${okMessage}`);
722	    } else {
723	      console.log(`  ${tier}: ERROR — ${result.message}`);
724	      hadError = true;
725	    }
726	  }
727	  if (skippedCount) {
728	    console.log(`  (${skippedCount} tier(s) skipped — no credentials set yet)`);
729	  }
730	  return hadError;
731	}
732	
733	async function validateAll(live) {
734	  console.log('Validating .env.shared and .env.<tier> files against .env.sample...\n');
735	  let anyErrors = false;
736	  anyErrors = printResult('.env.shared', validateSharedFile()) || anyErrors;
737	  for (const tier of TIERS) {
738	    anyErrors = printResult(`.env.${tier}`, validateTierFile(tier)) || anyErrors;
739	  }
740	
741	  if (live) {
742	    anyErrors =
743	      (await runLiveChecks(
744	        'Contentful Delivery API',
745	        liveCheckContentful,
746	        'CONTENTFUL_DELIVERY_TOKEN authenticates',
747	      )) || anyErrors;
748	    anyErrors =
749	      (await runLiveChecks('SFCC SLAS guest token', liveCheckSfcc, 'SLAS private-client guest token succeeded')) ||
750	      anyErrors;
751	  }
752	
753	  console.log('');
754	  if (anyErrors) {
755	    console.log('Validation FAILED — fix the ERROR line(s) above (warnings are informational, not blocking).');
756	    process.exitCode = 1;
757	  } else {
758	    console.log('No structural errors found. Warnings (if any) are informational.');
759	  }
760	}
761	
762	function switchTo(tier) {
763	  const merged = mergeSharedAndTier(tier);
764	  if (!merged) {
765	    console.log(`.env.shared and/or .env.${tier} don't exist yet. Run:`);
766	    console.log('  npm run env -- init');
767	    console.log('to scaffold every tier file at once, fill in the values, then switch again.');
768	    return;
769	  }
770	
771	  const orderedEntries = SAMPLE.filter((entry) => entry.scope !== 'auto');
772	  const orderedKeys = orderedEntries.map((entry) => entry.key);
773	  const extraKeys = [...merged.keys()].filter((key) => !orderedKeys.includes(key));
774	
775	  const lines = [
776	    `# Generated by \`npm run env -- ${tier}\` — do not edit directly.`,
777	    `# Edit .env.shared or .env.${tier} instead, then re-run the switch.`,
778	    '',
779	    `ENVIRONMENT_NAME=${tier}`,
780	    `DEPLOY_TARGET=${DEPLOY_TARGET_MAP[tier]}`,
781	    '',
782	  ];
783	  for (const { section, entries } of groupBySection(orderedEntries)) {
784	    const groupLines = entries
785	      .filter((entry) => merged.has(entry.key))
786	      .map((entry) => `${entry.key}=${merged.get(entry.key)}`);
787	    if (!groupLines.length) continue;
788	    lines.push(`# ── ${section} ──`, ...groupLines, '');
789	  }
790	  if (extraKeys.length) {
791	    lines.push('# ── Other ──', ...extraKeys.map((key) => `${key}=${merged.get(key)}`), '');
792	  }
793	  fs.writeFileSync(path.join(ROOT, '.env'), lines.join('\n').replace(/\n+$/, '\n'));
794	
795	  console.log(`Switched to "${tier}" (DEPLOY_TARGET=${DEPLOY_TARGET_MAP[tier]}).`);
796	  const blanks = [...merged.entries()].filter(([, value]) => !value).map(([key]) => key);
797	  if (blanks.length) {
798	    console.log(`\nHeads up — these values are still blank in .env.shared / .env.${tier}:`);
799	    blanks.forEach((key) => console.log(`  - ${key}`));
800	    console.log('\nRun `npm run env -- validate` for a fuller check.');
801	  }
802	}
803	
804	async function main() {
805	  const cmd = process.argv[2];
806	  if (!cmd) return reportCurrent();
807	  if (cmd === 'init') return initAll();
808	  if (cmd === 'validate') {
809	    // Tolerate `validate -- live` as well as `validate --live` — npm only
810	    // strips its own first `--`, so a habitual second `--` (easy to type,
811	    // since `npm run env -- <tier>` already needs one) would otherwise pass
812	    // '--' and 'live' through as two separate, unrecognised arguments and
813	    // silently skip the live check with no error.
814	    const rest = process.argv.slice(3);
815	    return validateAll(rest.includes('--live') || rest.includes('live'));
816	  }
817	  if (cmd === 'push') {
818	    const scope = process.argv[3];
819	    if (!GH_SCOPES.includes(scope)) {
820	      console.error(`Usage: npm run env -- push <${GH_SCOPES.join('|')}>`);
821	      process.exit(1);
822	    }
823	    return pushToGitHubEnvironment(scope);
824	  }
825	  if (!TIERS.includes(cmd)) {
826	    console.error(`Unknown command "${cmd}".`);
827	    printUsage();
828	    process.exit(1);
829	  }
830	  switchTo(cmd);
831	}
832	
833	main().catch((err) => {
834	  console.error(err.message ?? err);
835	  process.exit(1);
836	});
