#!/usr/bin/env node
// Manages the local `.env` across environment tiers (dev/test/sit/uat/staging/prod).
//
// Storage: .env.sample documents every key with a `# scope:shared|tier|personal|auto`
// comment on its own line above the key. Real values live in gitignored
// .env.shared (same across all tiers) and .env.<tier> (differs per tier) —
// never committed.
//
// Usage:
//   node scripts/switchEnv.mjs                — report the currently active tier
//   node scripts/switchEnv.mjs init            — scaffold .env.shared + every
//                                                 .env.<tier> at once (skips files
//                                                 that already exist), so a dev can
//                                                 fill in all tokens in one pass
//                                                 instead of tier by tier
//   node scripts/switchEnv.mjs validate [--live] — check every existing .env.shared /
//                                                 .env.<tier> file against
//                                                 .env.sample's schema, plus
//                                                 cross-checks (OCAPI host vs
//                                                 config/<tier>.js, Contentful
//                                                 environment id vs tier). With
//                                                 --live, also makes a real
//                                                 read-only Contentful Delivery
//                                                 API call AND a real SLAS guest
//                                                 (client_credentials) token
//                                                 request per tier, confirming
//                                                 the credentials actually work
//                                                 — not just that they're set
//   node scripts/switchEnv.mjs <tier>          — switch to <tier>, merging
//                                                 .env.shared + .env.<tier> into
//                                                 .env (tier values win on
//                                                 collision) and stamping
//                                                 ENVIRONMENT_NAME + DEPLOY_TARGET
//
// `init` also auto-fetches CONTENTFUL_ENVIRONMENT_ID, CONTENTFUL_DELIVERY_TOKEN,
// and CONTENTFUL_PREVIEW_TOKEN for every tier once .env.shared has a
// CONTENTFUL_MANAGEMENT_TOKEN + CONTENTFUL_SPACE_ID — reusing the same Content
// Management API read (client.apiKey.getMany / client.previewApiKey.get) and
// the same @ZimmermannAU/tier-1-approvers write gate as `npm run
// config:contentful` (scripts/contentful/setup/getConfig.mjs). The environment
// id comes from the same call — an API key's `environments` link only ever
// points at a real environment, so finding a token for a tier also confirms
// that tier's environment exists. It only reads existing API keys/environments
// — it never creates new ones in Contentful.
//
// SFCC values (org id, short code, OCAPI host, SLAS client id/secret) are NOT
// auto-fetched: there's no discovery API (you need the short code to call any
// SFCC API in the first place), and OAuth client secrets are never retrievable
// after creation. See .docs/integration/01-sfcc.md — these remain manual entry.
import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { createClient as createContentfulClient } from './contentful/setup/_shared.mjs';

const ROOT = process.cwd();
const TIERS = ['dev', 'test', 'sit', 'uat', 'staging', 'prod'];
// DEPLOY_TARGET picks config/{target}.js in pwa-kit-runtime's getConfig(), and also
// names the config file on disk for the cross-checks below. `prod` is the only tier
// where the local slug and the file/MRT target name diverge — see
// config/production.js and the `push:prod -t production` npm script.
const DEPLOY_TARGET_MAP = {
  dev: 'dev',
  test: 'test',
  sit: 'sit',
  uat: 'uat',
  staging: 'staging',
  prod: 'production',
};
// Confirmed environment strategy (2026-07-11): single Contentful space, per-tier
// environment id. `prod` is the only tier that doesn't just reuse its own slug.
const CONTENTFUL_ENV_MAP = {
  dev: 'dev',
  test: 'test',
  sit: 'sit',
  uat: 'uat',
  staging: 'staging',
  prod: 'master',
};

function readEnvFile(filePath) {
  if (!fs.existsSync(filePath)) return null;
  const entries = [];
  for (const raw of fs.readFileSync(filePath, 'utf8').split('\n')) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;
    entries.push([line.slice(0, eqIdx).trim(), line.slice(eqIdx + 1).trim()]);
  }
  return entries;
}

// Section headers look like `# ── Commerce / SFCC ───────────────`.
const SECTION_HEADER_RE = /^#\s*──+\s*(.+?)\s*──+\s*$/;
// Scope tags are their own comment line immediately above the KEY=value line
// (not trailing on the same line) — a trailing comment would make a blank
// placeholder look non-empty to the pre-commit .env.sample secret guard,
// which just checks whether anything follows the `=`.
const SCOPE_TAG_RE = /^#\s*scope:(shared|tier|personal|auto)\s*$/;

function parseSample() {
  const samplePath = path.join(ROOT, '.env.sample');
  const parsed = [];
  let currentSection = null;
  let pendingScope = null;
  for (const raw of fs.readFileSync(samplePath, 'utf8').split('\n')) {
    const line = raw.trim();
    const sectionMatch = line.match(SECTION_HEADER_RE);
    if (sectionMatch) {
      currentSection = sectionMatch[1];
      continue;
    }
    const scopeMatch = line.match(SCOPE_TAG_RE);
    if (scopeMatch) {
      pendingScope = scopeMatch[1];
      continue;
    }
    if (!line || line.startsWith('#')) continue;
    if (!pendingScope) continue; // a KEY=value line with no scope tag above it — not managed
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) {
      pendingScope = null;
      continue;
    }
    parsed.push({
      key: line.slice(0, eqIdx).trim(),
      value: line.slice(eqIdx + 1).trim(),
      scope: pendingScope,
      section: currentSection || 'Other',
    });
    pendingScope = null;
  }
  return parsed;
}

// Groups already-ordered entries by their .env.sample section, preserving the
// order sections first appear in. Used to print generated files with the same
// "# ── Section ──" grouping .env.sample has, instead of one flat key list.
function groupBySection(entries) {
  const groups = [];
  const bySection = new Map();
  for (const entry of entries) {
    if (!bySection.has(entry.section)) {
      const group = { section: entry.section, entries: [] };
      bySection.set(entry.section, group);
      groups.push(group);
    }
    bySection.get(entry.section).entries.push(entry);
  }
  return groups;
}

const SAMPLE = parseSample();
const SHARED_ENTRIES = SAMPLE.filter((entry) => entry.scope === 'shared');
const TIER_ENTRIES = SAMPLE.filter((entry) => entry.scope === 'tier');
const PERSONAL_ENTRIES = SAMPLE.filter((entry) => entry.scope === 'personal');
const SHARED_KEYS = new Set(SHARED_ENTRIES.map((entry) => entry.key));
const TIER_KEYS = new Set(TIER_ENTRIES.map((entry) => entry.key));
const PERSONAL_KEYS = new Set(PERSONAL_ENTRIES.map((entry) => entry.key));
// Everything that legitimately lives in .env.shared — shared (centralizable)
// plus personal (tier-independent, but per-developer and never centralized).
const SHARED_FILE_ENTRIES = [...SHARED_ENTRIES, ...PERSONAL_ENTRIES];
const SHARED_FILE_KEYS = new Set([...SHARED_KEYS, ...PERSONAL_KEYS]);
const AUTO_KEYS = new Set(SAMPLE.filter((entry) => entry.scope === 'auto').map((entry) => entry.key));

function scaffold(filePath, keys, label, carryDefaults) {
  const header = carryDefaults
    ? `# Generated by scripts/switchEnv.mjs — fill in real ${label} values.\n` +
      `# Gitignored — never commit this file. Values already in .env.sample (known\n` +
      `# public identifiers, e.g. GTM container ID) are carried over as a starting point.\n\n`
    : `# Generated by scripts/switchEnv.mjs — fill in real ${label} values.\n` +
      `# Gitignored — never commit this file. Tier-specific values always start blank\n` +
      `# here (even if .env.sample shows an example) — never copy another tier's value.\n\n`;
  const body =
    groupBySection(keys)
      .map(({ section, entries }) => {
        const groupLines = entries.map(({ key, value }) => `${key}=${carryDefaults ? value : ''}`);
        return `# ── ${section} ──\n${groupLines.join('\n')}`;
      })
      .join('\n\n') + '\n';
  fs.writeFileSync(filePath, header + body);
  const blankCount = carryDefaults ? keys.filter(({ value }) => !value).length : keys.length;
  console.log(
    `Created ${path.relative(
      ROOT,
      filePath,
    )} — fill in the ${blankCount} blank value(s) before switching to this tier.`,
  );
  return blankCount;
}

function reportCurrent() {
  const current = readEnvFile(path.join(ROOT, '.env'));
  const envName = current?.find(([key]) => key === 'ENVIRONMENT_NAME')?.[1] || '(not set)';
  console.log(`Current tier: ${envName}`);
  printUsage();
}

function printUsage() {
  console.log(`\nAvailable tiers: ${TIERS.join(', ')}`);
  console.log('Usage:');
  console.log('  npm run env                 — report the current tier');
  console.log('  npm run env -- init            — scaffold every .env.shared / .env.<tier> at once,');
  console.log('                                   pull values from GitHub Environments, then');
  console.log('                                   auto-fill Contentful tokens if possible');
  console.log('  npm run env -- validate        — check all existing env files for mistakes');
  console.log('  npm run env -- validate --live — also confirm Contentful + SFCC credentials actually work');
  console.log(`  npm run env -- push <${GH_SCOPES.join('|')}>`);
  console.log('                                   — tier-1-approvers only: push local values up to');
  console.log('                                   the matching GitHub Environment');
  console.log('  npm run env -- <tier>          — switch to <tier>');
}

async function initAll() {
  const sharedPath = path.join(ROOT, '.env.shared');
  const created = [];
  const skipped = [];
  let totalBlanks = 0;

  if (fs.existsSync(sharedPath)) {
    skipped.push('.env.shared');
  } else {
    totalBlanks += scaffold(sharedPath, SHARED_FILE_ENTRIES, 'shared (all tiers)', true);
    created.push('.env.shared');
  }

  for (const tier of TIERS) {
    const tierPath = path.join(ROOT, `.env.${tier}`);
    if (fs.existsSync(tierPath)) {
      skipped.push(`.env.${tier}`);
    } else {
      totalBlanks += scaffold(tierPath, TIER_ENTRIES, tier, false);
      created.push(`.env.${tier}`);
    }
  }

  console.log('');
  if (created.length) {
    console.log(`Created ${created.length} file(s): ${created.join(', ')}`);
    console.log(`Fill in the ${totalBlanks} blank value(s) across them in one pass, then run:`);
    console.log('  npm run env -- validate     (check everything is filled in correctly)');
    console.log('  npm run env -- <tier>       (activate one)');
  } else {
    console.log('Nothing to do — every .env.shared / .env.<tier> file already exists.');
  }
  if (skipped.length) {
    console.log(`Already existed, left untouched: ${skipped.join(', ')}`);
  }

  migrateSharedFromDotEnv();
  pullFromGitHubEnvironments();
  await syncContentfulTokens();
}

// ── GitHub Environments (centralized shared/tier storage) ──────────────────
// One GitHub Environment per scope — "shared" plus one per tier — each holding
// that scope's values as Environment-level Variables. Reading a Variable only
// needs repo collaborator access (gh auto-detects the repo from cwd, no need
// to pass -R). Writing needs repo Admin, which every tier-1-approver already
// holds — see `push` in main(). This intentionally stores real secrets here
// (not just non-sensitive config) — a deliberate, confirmed override of
// AGENTS.md's "secrets only in .env / Managed Runtime" rule, accepting that
// GitHub Variables are plaintext and readable by any repo collaborator.
const GH_SCOPES = ['shared', ...TIERS];

function listGitHubVariables(scope) {
  try {
    const raw = execSync(`gh variable list --env ${scope} --json name,value`, {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    return JSON.parse(raw);
  } catch {
    return null; // not authenticated, no access, or environment missing
  }
}

function pullFromGitHubEnvironments() {
  console.log('\nPulling values from GitHub Environments...');
  for (const scope of GH_SCOPES) {
    const filePath = path.join(ROOT, scope === 'shared' ? '.env.shared' : `.env.${scope}`);
    if (!fs.existsSync(filePath)) continue;
    const remoteVars = listGitHubVariables(scope);
    if (!remoteVars) {
      console.log(`  ${scope}: could not reach GitHub (not authenticated, no access, or environment missing)`);
      continue;
    }
    // Personal-scope keys (e.g. JIRA_API_TOKEN, CONTENTFUL_MANAGEMENT_TOKEN) are
    // never pulled, even if one somehow ended up on GitHub — each developer's
    // own value must never be overwritten by whoever last pushed.
    const filtered = scope === 'shared' ? remoteVars.filter(({ name }) => !PERSONAL_KEYS.has(name)) : remoteVars;
    const skippedPersonal = remoteVars.length - filtered.length;
    const updates = Object.fromEntries(filtered.map(({ name, value }) => [name, value]));
    const changes = upsertKeys(filePath, updates, true);
    const summary = changes.length
      ? changes.map((change) => `${change.action} ${change.key}`).join(', ')
      : 'already up to date';
    console.log(
      `  ${scope}: ${summary}${
        skippedPersonal ? ` (ignored ${skippedPersonal} personal-scope value(s) found on GitHub — see NOTE below)` : ''
      }`,
    );
  }
}

function pushToGitHubEnvironment(scope) {
  const filePath = path.join(ROOT, scope === 'shared' ? '.env.shared' : `.env.${scope}`);
  if (!fs.existsSync(filePath)) {
    console.error(`${path.relative(ROOT, filePath)} doesn't exist yet — run \`npm run env -- init\` first.`);
    process.exit(1);
  }

  const { approved, login } = isTier1Approver();
  if (!approved) {
    console.log(
      `Authenticated as '${login}' — not a tier-1-approver. Only tier-1-approvers can push to GitHub Environments.`,
    );
    return;
  }

  const allEntries = readEnvFile(filePath).filter(([, value]) => value);
  // Personal-scope keys never leave this machine — pushing your own Jira/CMA
  // token would put every teammate's actions under your identity.
  const entries = scope === 'shared' ? allEntries.filter(([key]) => !PERSONAL_KEYS.has(key)) : allEntries;
  const skippedPersonal = allEntries.length - entries.length;
  if (skippedPersonal) {
    console.log(
      `Excluding ${skippedPersonal} personal-scope value(s) — these are never pushed: ${allEntries
        .filter(([key]) => PERSONAL_KEYS.has(key))
        .map(([key]) => key)
        .join(', ')}`,
    );
  }
  if (!entries.length) {
    console.log(`Nothing to push — ${path.relative(ROOT, filePath)} has no filled-in, push-eligible values yet.`);
    return;
  }

  const tempFile = path.join(ROOT, `.env.push-${scope}.tmp`);
  fs.writeFileSync(tempFile, entries.map(([key, value]) => `${key}=${value}`).join('\n') + '\n');
  try {
    execSync(`gh variable set -f "${tempFile}" --env ${scope}`, { stdio: 'inherit' });
    console.log(`Pushed ${entries.length} value(s) to the "${scope}" GitHub Environment.`);
  } finally {
    fs.unlinkSync(tempFile);
  }
}

// ── Contentful auto-fetch (init) ────────────────────────────────────────────
// Same tier-1-approver gate as scripts/contentful/setup/getConfig.mjs — kept as
// a small local copy rather than importing it, since it isn't exported there.
function isTier1Approver() {
  try {
    const login = execSync('gh api user --jq .login', { encoding: 'utf8' }).trim();
    const membersRaw = execSync("gh api orgs/ZimmermannAU/teams/tier-1-approvers/members --jq '.[].login'", {
      encoding: 'utf8',
    }).trim();
    const members = membersRaw.split('\n').filter(Boolean);
    return { approved: members.includes(login), login };
  } catch {
    return { approved: false, login: 'unknown' };
  }
}

// contentful-management errors stringify their `.message` as the full raw API
// error body (headers, request id, everything) — pull out just the human part.
function contentfulErrorMessage(err) {
  try {
    const parsed = JSON.parse(err.message);
    if (parsed?.message) return parsed.message;
  } catch {
    // not JSON — fall through to the raw message
  }
  return err.message;
}

async function fetchContentfulTokenMap(managementToken, spaceId) {
  process.env.CONTENTFUL_MANAGEMENT_TOKEN = managementToken;
  process.env.CONTENTFUL_SPACE_ID = spaceId;
  const client = createContentfulClient();

  const { items: apiKeys } = await client.apiKey.getMany({ query: { limit: 100 } });
  const tokenMap = {};
  for (const key of apiKeys) {
    const envLink = key.environments?.[0];
    if (!envLink) continue;
    const envId = envLink.sys.id;
    let previewToken = '';
    if (key.preview_api_key?.sys?.id) {
      try {
        const previewKey = await client.previewApiKey.get({ previewApiKeyId: key.preview_api_key.sys.id });
        previewToken = previewKey.accessToken;
      } catch {
        // non-fatal — preview key may not exist yet
      }
    }
    tokenMap[envId] = { deliveryToken: key.accessToken, previewToken };
  }
  return tokenMap;
}

function parseEnvLines(content) {
  return content.split('\n').map((line) => {
    if (line.startsWith('#') || line.trim() === '') return { type: 'raw', value: line };
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) return { type: 'raw', value: line };
    return { type: 'var', key: line.slice(0, eqIdx).trim(), value: line.slice(eqIdx + 1) };
  });
}

function serializeEnvLines(lines) {
  return lines.map((line) => (line.type === 'var' ? `${line.key}=${line.value}` : line.value)).join('\n');
}

// Updates only the given keys in place, preserving comments/ordering/everything
// else — unlike scaffold(), which is only used for brand-new files. With
// fillOnly, an already-non-blank existing value is left alone instead of being
// overwritten — used for one-off migration from a pre-existing .env, where we
// never want to silently clobber something the dev already set by hand.
function upsertKeys(filePath, updates, canWrite, fillOnly = false) {
  const lines = parseEnvLines(fs.readFileSync(filePath, 'utf8'));
  const changes = [];
  for (const [key, value] of Object.entries(updates)) {
    if (!value) continue;
    const existing = lines.find((line) => line.type === 'var' && line.key === key);
    if (!existing) {
      lines.push({ type: 'var', key, value });
      changes.push({ action: 'add', key });
    } else if (!existing.value.trim()) {
      existing.value = value;
      changes.push({ action: 'fill', key });
    } else if (!fillOnly && existing.value.trim() !== value) {
      existing.value = value;
      changes.push({ action: 'update', key });
    }
  }
  if (changes.length && canWrite) {
    fs.writeFileSync(filePath, serializeEnvLines(lines));
  }
  return changes;
}

// One-off backfill: if a pre-existing root .env already has real values for
// shared-scope keys (e.g. a Contentful management token a dev added before
// this tiered setup existed), pull them into .env.shared. Only shared-scope
// keys — tier-scope values in an old .env can't be safely attributed to any
// one tier, so those are never auto-migrated. No tier-1 gate: this only copies
// a secret between two local gitignored files the developer already owns.
function migrateSharedFromDotEnv() {
  const dotEnvPath = path.join(ROOT, '.env');
  const sharedPath = path.join(ROOT, '.env.shared');
  if (!fs.existsSync(dotEnvPath) || !fs.existsSync(sharedPath)) return;

  const dotEnvMap = new Map(readEnvFile(dotEnvPath));
  const updates = {};
  for (const key of SHARED_FILE_KEYS) {
    const value = dotEnvMap.get(key);
    if (value) updates[key] = value;
  }
  if (!Object.keys(updates).length) return;

  const changes = upsertKeys(sharedPath, updates, true, true);
  if (changes.length) {
    console.log(
      `\nFound already-filled value(s) in your existing .env — copied into .env.shared: ${changes
        .map((change) => change.key)
        .join(', ')}`,
    );
  }
}

async function syncContentfulTokens() {
  const sharedPath = path.join(ROOT, '.env.shared');
  if (!fs.existsSync(sharedPath)) return;

  const sharedMap = new Map(readEnvFile(sharedPath));
  const managementToken = sharedMap.get('CONTENTFUL_MANAGEMENT_TOKEN');
  const spaceId = sharedMap.get('CONTENTFUL_SPACE_ID');
  if (!managementToken || !spaceId) {
    console.log(
      '\n(Skipping Contentful token auto-fetch — fill in CONTENTFUL_MANAGEMENT_TOKEN and CONTENTFUL_SPACE_ID in .env.shared, then run `npm run env -- init` again.)',
    );
    return;
  }

  const { approved, login } = isTier1Approver();
  console.log(
    `\nFetching live Contentful API keys (authenticated as '${login}'${
      approved ? ', tier-1-approver' : ' — read-only, not a tier-1-approver'
    })...`,
  );

  let tokenMap;
  try {
    tokenMap = await fetchContentfulTokenMap(managementToken, spaceId);
  } catch (err) {
    console.log(`  Could not reach Contentful: ${contentfulErrorMessage(err)}`);
    return;
  }

  for (const tier of TIERS) {
    const tierPath = path.join(ROOT, `.env.${tier}`);
    if (!fs.existsSync(tierPath)) continue; // init scaffolds these first; nothing to update yet
    const contentfulEnvId = CONTENTFUL_ENV_MAP[tier];
    const tokens = tokenMap[contentfulEnvId];
    if (!tokens) {
      console.log(`  ${tier}: no Contentful API key found for environment "${contentfulEnvId}"`);
      continue;
    }
    const changes = upsertKeys(
      tierPath,
      {
        // tokenMap is keyed by real environment IDs from the API key's own
        // `environments` link — if we found a token for it, the environment
        // definitely exists, so it's safe to fill this in from the same call.
        CONTENTFUL_ENVIRONMENT_ID: contentfulEnvId,
        CONTENTFUL_DELIVERY_TOKEN: tokens.deliveryToken,
        CONTENTFUL_PREVIEW_TOKEN: tokens.previewToken,
      },
      approved,
    );
    if (!changes.length) {
      console.log(`  ${tier}: already up to date`);
    } else if (!approved) {
      console.log(`  ${tier}: ${changes.length} change(s) available — read-only, ask a tier-1-approver to run this`);
    } else {
      console.log(`  ${tier}: ${changes.map((change) => `${change.action} ${change.key}`).join(', ')}`);
    }
  }
}

function extractOcapiHost(tier) {
  const configPath = path.join(ROOT, 'config', `${DEPLOY_TARGET_MAP[tier]}.js`);
  if (!fs.existsSync(configPath)) return null;
  const content = fs.readFileSync(configPath, 'utf8');
  const match = content.match(/host:\s*'([^']+)'[^}]*path:\s*'ocapi'/);
  return match ? match[1] : null;
}

function validateKeyPlacement(entries, ownScope, ownLabel, otherScope, otherLabel) {
  const errors = [];
  const warnings = [];
  let blankCount = 0;
  const seen = new Map();
  for (const [key, value] of entries) {
    if (seen.has(key)) errors.push(`duplicate key ${key}`);
    seen.set(key, value);
    if (AUTO_KEYS.has(key)) {
      errors.push(`${key} should never be hand-set — it's auto-generated on every switch`);
    } else if (otherScope.has(key)) {
      errors.push(
        `${key} is a ${otherLabel}-scope key — belongs in ${
          otherLabel === 'shared' ? '.env.shared' : 'a .env.<tier> file'
        }, not here`,
      );
    } else if (!ownScope.has(key)) {
      warnings.push(`${key} isn't in .env.sample — typo, or the sample needs updating`);
    }
  }
  // Blank/missing values are extremely common (most integrations aren't
  // provisioned yet) — collapsed to one count instead of one line per key,
  // so real problems (errors, misplaced/unknown keys) aren't buried under them.
  for (const key of ownScope) {
    if (!seen.has(key) || !seen.get(key)) blankCount += 1;
  }
  return { errors, warnings, blankCount, seen };
}

function validateSharedFile() {
  const filePath = path.join(ROOT, '.env.shared');
  if (!fs.existsSync(filePath)) return { skipped: true };
  return validateKeyPlacement(readEnvFile(filePath), SHARED_FILE_KEYS, 'shared', TIER_KEYS, 'tier');
}

function validateTierFile(tier) {
  const filePath = path.join(ROOT, `.env.${tier}`);
  if (!fs.existsSync(filePath)) return { skipped: true };
  const result = validateKeyPlacement(readEnvFile(filePath), TIER_KEYS, 'tier', SHARED_FILE_KEYS, 'shared');

  const ocapiHost = result.seen.get('COMMERCE_API_OCAPI_HOST');
  if (ocapiHost) {
    if (ocapiHost.includes('TODO')) {
      result.errors.push(
        'COMMERCE_API_OCAPI_HOST still has a TODO placeholder — replace with the real SFCC sandbox host',
      );
    }
    const expectedHost = extractOcapiHost(tier);
    if (expectedHost && !ocapiHost.includes('TODO') && ocapiHost !== expectedHost) {
      result.errors.push(
        `COMMERCE_API_OCAPI_HOST=${ocapiHost} doesn't match config/${DEPLOY_TARGET_MAP[tier]}.js's proxy host (${expectedHost}) — likely copy-pasted from another tier`,
      );
    }
  }

  const contentfulEnv = result.seen.get('CONTENTFUL_ENVIRONMENT_ID');
  const expectedContentfulEnv = CONTENTFUL_ENV_MAP[tier];
  if (contentfulEnv && contentfulEnv !== expectedContentfulEnv) {
    result.warnings.push(
      `CONTENTFUL_ENVIRONMENT_ID=${contentfulEnv} — expected "${expectedContentfulEnv}" for the ${tier} tier per the confirmed environment strategy`,
    );
  }

  return result;
}

function printResult(label, result) {
  if (result.skipped) {
    console.log(`${label}: not created yet (run \`npm run env -- init\`)`);
    return false;
  }
  const { errors, warnings, blankCount } = result;
  if (!errors.length && !warnings.length && !blankCount) {
    console.log(`${label}: OK`);
    return false;
  }
  console.log(`${label}:`);
  errors.forEach((error) => console.log(`  ERROR   ${error}`));
  warnings.forEach((warning) => console.log(`  warning ${warning}`));
  if (blankCount) {
    console.log(`  (${blankCount} blank value(s) in ${label})`);
  }
  return errors.length > 0;
}

// Merges .env.shared + .env.<tier> (tier wins on collision). Returns null if
// either file doesn't exist yet.
function mergeSharedAndTier(tier) {
  const sharedPath = path.join(ROOT, '.env.shared');
  const tierPath = path.join(ROOT, `.env.${tier}`);
  if (!fs.existsSync(sharedPath) || !fs.existsSync(tierPath)) return null;

  const merged = new Map();
  for (const [key, value] of readEnvFile(sharedPath)) merged.set(key, value);
  for (const [key, value] of readEnvFile(tierPath)) merged.set(key, value); // tier wins
  merged.delete('ENVIRONMENT_NAME');
  merged.delete('DEPLOY_TARGET');
  return merged;
}

// Real, read-only call to the Contentful Content Delivery API — confirms the
// delivery token actually authenticates for that space/environment, not just
// that it's non-blank.
async function liveCheckContentful(tier) {
  const merged = mergeSharedAndTier(tier);
  if (!merged) return { skipped: true, reason: '.env.shared and/or .env.<tier> not created yet' };

  const deliveryToken = merged.get('CONTENTFUL_DELIVERY_TOKEN');
  const spaceId = merged.get('CONTENTFUL_SPACE_ID');
  const envId = merged.get('CONTENTFUL_ENVIRONMENT_ID');
  if (!deliveryToken || !spaceId || !envId) {
    return {
      skipped: true,
      reason: 'CONTENTFUL_DELIVERY_TOKEN / CONTENTFUL_SPACE_ID / CONTENTFUL_ENVIRONMENT_ID not all filled in',
    };
  }

  const url = `https://cdn.contentful.com/spaces/${spaceId}/environments/${envId}/entries?limit=1`;
  try {
    const res = await fetch(url, { headers: { Authorization: `Bearer ${deliveryToken}` } });
    if (res.ok) return { ok: true };
    return { ok: false, message: `HTTP ${res.status} from Contentful Delivery API` };
  } catch (err) {
    return { ok: false, message: `network error — ${err.message}` };
  }
}

// Real, read-only SLAS guest-token request — the same private-client
// client_credentials grant every anonymous shopper visit already triggers
// (confirmed against the actual commerce-sdk-react/commerce-sdk-isomorphic
// `loginGuestUserPrivate` implementation, not guessed). Doesn't touch any
// customer/commerce data — just proves the short code, org id, and SLAS
// client id/secret are all correct for that tier's SFCC sandbox.
async function liveCheckSfcc(tier) {
  const merged = mergeSharedAndTier(tier);
  if (!merged) return { skipped: true, reason: '.env.shared and/or .env.<tier> not created yet' };

  const shortCode = merged.get('COMMERCE_API_SHORT_CODE');
  const organizationId = merged.get('COMMERCE_API_ORGANIZATION_ID');
  const clientId = merged.get('COMMERCE_API_CLIENT_ID');
  const clientSecret = merged.get('PWA_KIT_SLAS_CLIENT_SECRET');
  const siteId = merged.get('COMMERCE_API_SITE_ID');
  if (!shortCode || !organizationId || !clientId || !clientSecret || !siteId) {
    return {
      skipped: true,
      reason:
        'COMMERCE_API_SHORT_CODE / ORGANIZATION_ID / CLIENT_ID / PWA_KIT_SLAS_CLIENT_SECRET / SITE_ID not all filled in',
    };
  }

  const url = `https://${shortCode}.api.commercecloud.salesforce.com/shopper/auth/v1/organizations/${organizationId}/oauth2/token`;
  const basicAuth = Buffer.from(`${clientId}:${clientSecret}`).toString('base64');
  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: {
        Authorization: `Basic ${basicAuth}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: new URLSearchParams({ grant_type: 'client_credentials', channel_id: siteId }).toString(),
    });
    if (res.ok) return { ok: true };
    return { ok: false, message: `HTTP ${res.status} from SLAS token endpoint (${shortCode})` };
  } catch (err) {
    return { ok: false, message: `network error — ${err.message}` };
  }
}

// Runs a live-check function across every tier, printing OK/ERROR per tier
// and collapsing skips (missing credentials) to a single trailing count —
// same "don't clutter with what can't be tested" approach as the static
// blank-value counts above.
async function runLiveChecks(sectionLabel, checkFn, okMessage) {
  console.log(`\n── Live checks (${sectionLabel}) ──`);
  let skippedCount = 0;
  let hadError = false;
  for (const tier of TIERS) {
    const result = await checkFn(tier);
    if (result.skipped) {
      skippedCount += 1;
    } else if (result.ok) {
      console.log(`  ${tier}: OK — ${okMessage}`);
    } else {
      console.log(`  ${tier}: ERROR — ${result.message}`);
      hadError = true;
    }
  }
  if (skippedCount) {
    console.log(`  (${skippedCount} tier(s) skipped — no credentials set yet)`);
  }
  return hadError;
}

async function validateAll(live) {
  console.log('Validating .env.shared and .env.<tier> files against .env.sample...\n');
  let anyErrors = false;
  anyErrors = printResult('.env.shared', validateSharedFile()) || anyErrors;
  for (const tier of TIERS) {
    anyErrors = printResult(`.env.${tier}`, validateTierFile(tier)) || anyErrors;
  }

  if (live) {
    anyErrors =
      (await runLiveChecks(
        'Contentful Delivery API',
        liveCheckContentful,
        'CONTENTFUL_DELIVERY_TOKEN authenticates',
      )) || anyErrors;
    anyErrors =
      (await runLiveChecks('SFCC SLAS guest token', liveCheckSfcc, 'SLAS private-client guest token succeeded')) ||
      anyErrors;
  }

  console.log('');
  if (anyErrors) {
    console.log('Validation FAILED — fix the ERROR line(s) above (warnings are informational, not blocking).');
    process.exitCode = 1;
  } else {
    console.log('No structural errors found. Warnings (if any) are informational.');
  }
}

function switchTo(tier) {
  const merged = mergeSharedAndTier(tier);
  if (!merged) {
    console.log(`.env.shared and/or .env.${tier} don't exist yet. Run:`);
    console.log('  npm run env -- init');
    console.log('to scaffold every tier file at once, fill in the values, then switch again.');
    return;
  }

  const orderedEntries = SAMPLE.filter((entry) => entry.scope !== 'auto');
  const orderedKeys = orderedEntries.map((entry) => entry.key);
  const extraKeys = [...merged.keys()].filter((key) => !orderedKeys.includes(key));

  const lines = [
    `# Generated by \`npm run env -- ${tier}\` — do not edit directly.`,
    `# Edit .env.shared or .env.${tier} instead, then re-run the switch.`,
    '',
    `ENVIRONMENT_NAME=${tier}`,
    `DEPLOY_TARGET=${DEPLOY_TARGET_MAP[tier]}`,
    '',
  ];
  for (const { section, entries } of groupBySection(orderedEntries)) {
    const groupLines = entries
      .filter((entry) => merged.has(entry.key))
      .map((entry) => `${entry.key}=${merged.get(entry.key)}`);
    if (!groupLines.length) continue;
    lines.push(`# ── ${section} ──`, ...groupLines, '');
  }
  if (extraKeys.length) {
    lines.push('# ── Other ──', ...extraKeys.map((key) => `${key}=${merged.get(key)}`), '');
  }
  fs.writeFileSync(path.join(ROOT, '.env'), lines.join('\n').replace(/\n+$/, '\n'));

  console.log(`Switched to "${tier}" (DEPLOY_TARGET=${DEPLOY_TARGET_MAP[tier]}).`);
  const blanks = [...merged.entries()].filter(([, value]) => !value).map(([key]) => key);
  if (blanks.length) {
    console.log(`\nHeads up — these values are still blank in .env.shared / .env.${tier}:`);
    blanks.forEach((key) => console.log(`  - ${key}`));
    console.log('\nRun `npm run env -- validate` for a fuller check.');
  }
}

async function main() {
  const cmd = process.argv[2];
  if (!cmd) return reportCurrent();
  if (cmd === 'init') return initAll();
  if (cmd === 'validate') {
    // Tolerate `validate -- live` as well as `validate --live` — npm only
    // strips its own first `--`, so a habitual second `--` (easy to type,
    // since `npm run env -- <tier>` already needs one) would otherwise pass
    // '--' and 'live' through as two separate, unrecognised arguments and
    // silently skip the live check with no error.
    const rest = process.argv.slice(3);
    return validateAll(rest.includes('--live') || rest.includes('live'));
  }
  if (cmd === 'push') {
    const scope = process.argv[3];
    if (!GH_SCOPES.includes(scope)) {
      console.error(`Usage: npm run env -- push <${GH_SCOPES.join('|')}>`);
      process.exit(1);
    }
    return pushToGitHubEnvironment(scope);
  }
  if (!TIERS.includes(cmd)) {
    console.error(`Unknown command "${cmd}".`);
    printUsage();
    process.exit(1);
  }
  switchTo(cmd);
}

main().catch((err) => {
  console.error(err.message ?? err);
  process.exit(1);
});

